\caption{\gls*{kiplmc1}}\label{alg:KIPLMC1}
\begin{algorithmic}[1]
\Require $\gamma, \eta > 0$, $N, M \in \bN$
\State Compute the covariance matrix $C$ given in \eqref{eq:covariancemat} and its Cholesky decomposition $C = H H^\top$.
\State Draw $\theta_0, X^i_0, V^\theta_0, V^{x_i}_0$, for $i\in [N]$
    \For{$n = 0:M-1$}
    \State Draw: $\xi_n^0,\xi_n^{0,\prime}\in\mathbb{R}^{d_\theta}$ and $\xi_n^i, \xi_n^{i,\prime}\in\mathbb{R}^{d_x}$, for $i=1,\dots, N$, from standard Gaussians and define
    \begin{align*}
    \varepsilon_n^{i} &= H_{11} \xi_n^{i}, &
    \varepsilon_n^{i,\prime} = H_{21} \xi_n^i + H_{22}  \xi_n^{i,\prime}
\end{align*}
for $i = 0, \ldots, N$.
    \State Compute the average gradient of the potential:
    \begin{align*}
    F_{n}^{\theta} &= \frac{1}{N} \sum_{i=1}^N \nabla_\theta U(\theta_n, X^i_n), & 
    F_{n}^{x_i} = \nabla_x U(\theta_n, X^i_n).
    \end{align*}
    Update the parameters, particles and their momenta:
    \small
    \begin{align}
    \theta_{n+1} &= \theta_n + \psi_1^\eta V^{\theta}_n - {\psi_2^\eta} F_{n}^{\theta} + \sqrt{\frac{2\gamma}{N}} \varepsilon^{0, \prime}_{n} \nonumber \\
    X^i_{n+1} &= X^i_n + \psi_1^\eta V^{x_i}_n - \psi_2^\eta F_{n}^{x_i} + \sqrt{2\gamma}\varepsilon_{n}^{i,\prime} \tag{KIPLMC1} \label{eq:KIPLMC1} \\
    V^{\theta}_{n+1} &= \psi_0^\eta V^{\theta}_n - \psi_1^\eta F_{n}^{\theta} + \sqrt{\frac{2\gamma}{N}} \varepsilon^0_{n} \nonumber \\
    V^{x_i}_{n+1} &= \psi_0^\eta V^{x_i}_n - \psi_1^\eta F_{n}^{x_i} + \sqrt{2\gamma} \varepsilon^i_{n} \nonumber
    \end{align}
    for $i\in [N]$.
    \normalsize
    \EndFor
\State Output: $(\theta_{M}, X^1_M, \ldots, X^N_M)$
\end{algorithmic}

\label{assump:strongconvexity}
Suppose $U\in C^2(\mathbb{R}^{d_\theta+d_x})$. There exists a constant $\mu>0$ such that, for all $z,z'\in \mathbb{R}^{d_\theta+d_x}$,
\begin{equation*}
\langle z-z', \nabla U(z) - \nabla U(z')\rangle \geq \mu \|z-z'\|^2.
\end{equation*}
Since $U\in C^2$, this is equivalent to $\nabla^2 U(z)\succeq \mu I$ for all $z\in \mathbb{R}^{d_\theta+d_x}$, i.e., $U$ is $\mu$-strongly convex.

\label{assump:lipschitz}
There exists a constant $L>0$ such that, for all $z,z'\in \mathbb{R}^{d_\theta+d_x}$,
\begin{equation*}
\|\nabla U(z) - \nabla U(z')\| \leq L \|z-z'\|.
\end{equation*}

\label{prop:stationary}
Let $\pi_\Theta$ be the $\theta$-marginal of the stationary measure of the KIPLD. Then, we can write its density as
\begin{align}
\pi_\Theta(\theta) \propto \exp( - N \kappa(\theta)).
\end{align}
where $\kappa(\theta) = - \log p_\theta(y)$.

\label{prop:mmleerror}
Under \ref{assump:strongconvexity}, the function $\theta \mapsto p_\theta(y)$ is $\mu$-strongly log-concave. Furthermore, we have
\begin{equation*}
W_2(\pi_\Theta, \delta_{\bar{\theta}_\star})\leq \sqrt{\frac{d_\theta}{\mu N}},
\end{equation*}
where $\bar{\theta}_\star = \argmax_{\theta\in\mathbb{R}^{d_\theta}} \log p_\theta(y)$,
which is unique.

\label{prop:kipld_conv}
Let $(\bm{\theta}_t)_{t\geq 0}$ be the $\theta$-marginal of a solution to the KIPLD, initialised so that
\begin{align*}
\Z_0
:=(\bm\theta_0,N^{-1/2}\X_0^1,\ldots,N^{-1/2}\X_0^N)^\intercal
\sim\nu,
\end{align*}
where $\nu\in\mathcal P(\mathbb R^{d_z})$ has finite second moment and $d_z=d_\theta+Nd_x$.  Independently of $\Z_0$, initialise the mutually independent velocities as
\begin{align*}
\V_0^\theta&\sim\mathcal N(0,N^{-1}\mathbb I_{d_\theta}),&
\V_0^{x_i}\sim\mathcal N(0,\mathbb I_{d_x}),\qquad i\in[N].
\end{align*}
Then, under \ref{assump:strongconvexity} and \ref{assump:lipschitz} and for $\gamma \geq \sqrt{\mu + L}$, for every $t\geq0$ we have
\begin{align*}
W_2(\mathcal{L}(\bm{\theta}_t), \pi_\Theta) \leq \sqrt{2} \exp\left(-\frac{\mu}{\gamma}t\right) \mathbb{E}[\|\Z_0 - \bar{Z}_\star\|^2]^{1/2},
\end{align*}
where $\bar{Z}_\star\sim\widetilde\pi_Z$, the position marginal of the invariant measure $\widetilde\pi$ in Lemma~\ref{lem:scaledstat}, is drawn independently of $\Z_0$.

\label{thm:KPLMC1} Let $(\theta_n)_{n\in\bN}$ be the iterates of \gls*{kiplmc1} and suppose that the process is initialised as $Z_0\sim \nu$, where $\nu\in\mathcal{P}(\mathbb{R}^{d_z})$ has bounded second moments, $V^\theta_0\sim \mathcal{N}(0, N^{-1}\mathbb{I}_{d_\theta})$ and $V^{x_i}_0 \sim \mathcal{N}(0, \mathbb{I}_{d_x})$, for $i=1,\dots,N$. Under Assumptions \ref{assump:strongconvexity} and \ref{assump:lipschitz} and with $\gamma\geq \sqrt{\mu+L}$ and $\eta \leq \mu/(4\gamma L)$, we have
\begin{align*}
\bE[\|\theta_n - \bar{\theta}_\star\|^2]^{1/2} &\leq C_1 \left(1-\frac{0.75\mu\eta}{\gamma}\right)^n + \eta C_2 + \sqrt{\frac{C_3}{N}},
\end{align*}
where
\begin{align*}
C_1 &= \sqrt{2} \bE[\|Z_0 - \bar{Z}_\star\|^2]^{1/2},
\qquad C_2 = \sqrt{2}\frac{L}{\mu} \sqrt{\frac{d_\theta + N d_x}{N}}, \qquad
C_3 = \frac{d_\theta}{\mu},
\end{align*}
where $Z_0=(\theta_0, N^{-1/2} X^1_0,\dots, N^{-1/2} X^N_0)^\intercal$, the initialisation step of the \gls*{kiplmc1} where $\bar{Z}_\star\sim\widetilde\pi_Z$ and $\widetilde\pi_Z$ is the position marginal of the invariant measure $\widetilde\pi$ described in Lemma~\ref{lem:scaledstat}.

\label{thm:KIPLMC2}

Let $(\theta_n)_{n\in\mathbb{N}}$ be the iterates of \gls*{kiplmc2}, set $d_z=d_\theta+Nd_x$, and define the rescaled initial position
\begin{align*}
Z_0=(\theta_0,N^{-1/2}X_0^1,\ldots,N^{-1/2}X_0^N)^\intercal.
\end{align*}
Suppose that $Z_0\sim\nu$, where $\nu\in\mathcal{P}(\mathbb{R}^{d_z})$ has finite second moment, and, independently of $Z_0$, initialise the mutually independent velocities as
\begin{align*}
V_0^\theta&\sim\mathcal{N}(0,N^{-1}\mathbb{I}_{d_\theta}), &
V_0^{x_i}\sim\mathcal{N}(0,\mathbb{I}_{d_x}),\qquad i\in[N].
\end{align*}
Under Assumptions~\ref{assump:strongconvexity} and~\ref{assump:lipschitz}, if $\gamma\geq2\sqrt{L}$ and $0<\eta\leq\mu/(33\gamma^3)$, then, for every $n\in\mathbb{N}$,
letting $\widetilde\pi_Z$ denote the position marginal of the invariant measure
$\widetilde\pi$ in Lemma~\ref{lem:scaledstat}, we have
\begin{align*}
\bE[\|\theta_n-\bar{\theta}_\star\|^2]^{1/2}
&\lesssim (\sqrt N\,W_2(\nu,\widetilde\pi_Z) +\eta N\sqrt{d_\theta+Nd_x})
\exp\left(-\frac{\mu\eta n}{6\gamma}\right)\\
&\quad+\eta\sqrt{N(d_\theta+Nd_x)}
+\sqrt{\frac{d_\theta}{N}}.
\end{align*}
The implicit constant depends only on $\mu$, $L$, and $\gamma$; in particular,
it is independent of $n$, $N$, $\eta$, $d_\theta$, and $d_x$.

[On \ref{assump:strongconvexity} and \ref{assump:lipschitz}]\label{rem:convexity}

We will discuss this problem and our assumptions. Writing $z=(\theta,x)$ and $z'=(\theta',x')$, using
$\|(a-b,-a+b)\|\leq2\|(a,b)\|$ and the fact that the logistic function is $1/4$-Lipschitz, we obtain
\begin{equation*}
\begin{aligned}
\|\nabla U(z)-\nabla U(z')\|
&\leq\left(\frac{2}{\sigma^2}+\frac14\sum_{j=1}^{d_y}\|v_j\|^2\right)\|z-z'\|.
\end{aligned}
\end{equation*}
Hence, \ref{assump:lipschitz} is satisfied \citep{akyildiz2025interacting}.

For \ref{assump:strongconvexity}, note that $d_\theta=d_x$ in this model. Set
$q_j(x):=s(v_j^\intercal x)\bigl(1-s(v_j^\intercal x)\bigr)$ and
$Q(x):=\sum_{j=1}^{d_y}q_j(x)v_jv_j^\intercal$. Then
\begin{equation*}
\begin{aligned}
\nabla^2U(z)
&=\frac1{\sigma^2}
\begin{pmatrix}
I_{d_x}&-I_{d_x}\\
-I_{d_x}&I_{d_x}
\end{pmatrix} +\begin{pmatrix}
0&0\\
0&Q(x)
\end{pmatrix}.
\end{aligned}
\end{equation*}
Indeed, for $u,w\in\mathbb R^{d_x}$, $(u, w)^\intercal\nabla^2U(z)(u,w)$ vanishes if and only if $u=w$ and $v_j^\intercal w=0$ for every $j$.
Thus, $U$ is strictly convex provided that
$\operatorname{span}\{v_1,\ldots,v_{d_y}\}=\mathbb R^{d_x}$. Consequently, \ref{assump:strongconvexity} is not satisfied without further regularisation; nevertheless, we believe that this remains a useful illustrative example.

\label{prop:kipld_standard_ud}
Let $$(\bm{\theta}_t,\X_t^1,\ldots,\X_t^N,\V_t^\theta,\V_t^{x_1},\ldots,\V_t^{x_N})_{t\geq 0}$$ solve \eqref{eq:KIPLD}. Define
\begin{align*}
\widetilde{\bm{\theta}}_t &:= \bm{\theta}_{\sqrt{N}t}, \qquad
\widetilde{\X}_t^i := N^{-1/2}\X^i_{\sqrt{N}t}, \\
\widetilde{\V}_t^\theta &:= \sqrt{N}\V^\theta_{\sqrt{N}t}, \qquad
\widetilde{\V}_t^{x_i} := \V^{x_i}_{\sqrt{N}t},
\end{align*}
for $i\in[N]$, and set
\begin{align*}
\widetilde{\Z}_t &:= (\widetilde{\bm{\theta}}_t,\widetilde{\X}_t^1,\ldots,\widetilde{\X}_t^N)^\intercal \in \bR^{d_\theta+Nd_x}, \\
\widetilde{\V}_t^z &:= (\widetilde{\V}_t^\theta,\widetilde{\V}_t^{x_1},\ldots,\widetilde{\V}_t^{x_N})^\intercal \in \bR^{d_\theta+Nd_x},
\end{align*}
and
\begin{align}
\bar U_N(\theta,x_1,\ldots,x_N) &:= \frac{1}{N}\sum_{i=1}^N U(\theta,\sqrt{N}\,x_i), \label{eq:barU}
\end{align}
and $\widetilde{\gamma} := \sqrt{N}\gamma$. Then there exists a $\bR^{d_\theta+Nd_x}$-valued Brownian motion $(\widetilde{\B}_t)_{t\ge 0}$ such that
\begin{align}
\md \widetilde{\Z}_t &= \widetilde{\V}_t^z\,\md t, \label{eq:simplesde_scaled} \\
\md \widetilde{\V}_t^z &= -\widetilde{\gamma}\,\widetilde{\V}_t^z\,\md t
- N\nabla_z \bar U_N(\widetilde{\Z}_t)\,\md t
+ \sqrt{2\widetilde{\gamma}}\,\md \widetilde{\B}_t. \nonumber
\end{align}

[Stationary measure for \eqref{eq:simplesde_scaled}]\label{lem:scaledstat}
The measure $\tilde{\pi}$ invariant for the dynamics in \eqref{eq:simplesde_scaled} is given as
\begin{equation}
\tilde{\pi}(\md \tilde{z}, \md \tilde{v}) \propto \exp\left(-N\bar{U}_N(\tilde{z}) -\frac{1}{2}\|\tilde{v}\|^2\right)\md \tilde{z} \md \tilde{v},
\end{equation}
for all $\tilde{z},\tilde{v}\in\mathbb{R}^{d_z}$, where $d_z=d_\theta+Nd_x$.

[Strong convexity of $\bar{U}_N$]\label{lem:strongconvexity_barU} Under \ref{assump:strongconvexity}, the function $\bar{U}_N: \bR^{d_\theta + Nd_x} \to \bR$ as defined in \eqref{eq:barU} is $\mu$-strongly convex
\begin{align*}
    \langle z-z^\prime, \nabla \bar{U}_N(z) - \nabla \bar{U}_N(z^\prime)\rangle \geq \mu \|z-z^\prime\|^2,
\end{align*}
for all $z, z^\prime \in \bR^{d_\theta + Nd_x}$ and $N \in \bN$.

[Gradient Lipschitzness of $\bar{U}_N$]\label{lem:gradientlipschitz_barU}
Under \ref{assump:lipschitz}, the function $\bar{U}_N: \bR^{d_\theta + Nd_x} \to \bR$ as defined in \eqref{eq:barU} is $L$-gradient Lipschitz
\begin{align*}
    \|\nabla \bar{U}_N(z) - \nabla \bar{U}_N(z^\prime)\| \leq L \|z-z^\prime\|,
\end{align*}
for all $z, z^\prime \in \bR^{d_\theta + Nd_x}$ and $N \in \bN$.

\label{prop:kipld_kiplmc1}
Let the sequence $(\widetilde{Z}_k,\widetilde{V}_k^z)_{k\geq 0}$ be the exponential-integrator discretisation of the rescaled underdamped diffusion \eqref{eq:simplesde_scaled} with friction parameter $\widetilde{\gamma}=\sqrt{N}\gamma$ and step-size $\widetilde{\eta}=\eta/\sqrt{N}$. Define the unscaled variables by
\begin{align*}
\widetilde{\theta}_k &= \theta_k,\qquad \widetilde{X}_k^i = N^{-1/2}X_k^i,\\
\widetilde{V}_k^\theta &= \sqrt{N}V_k^\theta,\qquad \widetilde{V}_k^{x_i} = V_k^{x_i},
\end{align*}
for each $i\in[N]$. Then, after the corresponding rescaling of the Gaussian noise variables, the resulting recursion in $(\theta_k,X_k^i,V_k^\theta,V_k^{x_i})_{i\in[N]}$ coincides exactly with the \gls*{kiplmc1} scheme defined in Section~\ref{subsec:kiplmc1}.

\label{prop:kipld_kiplmc2}
Let $(\widetilde{Z}_k,\widetilde{V}_k^z)_{k\geq 0}$ be the OBABO discretisation of the rescaled underdamped diffusion \eqref{eq:simplesde_scaled} with friction parameter $\widetilde{\gamma}=\sqrt{N}\gamma$ and step-size $\widetilde{\eta}=\eta/\sqrt{N}$. Define the unscaled variables by
\begin{align*}
\widetilde{\theta}_k &= \theta_k,\qquad \widetilde{X}_k^i = N^{-1/2}X_k^i,\\
\widetilde{V}_k^\theta &= \sqrt{N}V_k^\theta,\qquad \widetilde{V}_k^{x_i} = V_k^{x_i},
\end{align*}
for each $i\in[N]$. Then the resulting recursion in $(\theta_k,X_k^i,V_k^\theta,V_k^{x_i})_{i\in[N]}$ coincides exactly with the \gls*{kiplmc2} scheme defined in Algorithm~\ref{alg:KIPLMC2}.
